package app.xiaohe.tests;

import android.content.Context;
import android.database.Cursor;
import app.xiaohe.assistant.*;
import org.json.*;
import java.time.*;
import java.time.temporal.TemporalAdjusters;
import java.util.*;

/** 1.2 policy checks: uncertainty is retained without becoming a cleanup queue. */
public final class AssistantFeelSmoke {
  private static int checks=0,sequence=0;
  private static final long BASE=OffsetDateTime.parse("2030-10-09T10:00:00+08:00").toInstant().toEpochMilli();
  private static void ok(boolean value,String why){checks++;if(!value)throw new AssertionError("Assistant feel "+checks+": "+why);}
  private static JSONObject message(Store db,String text,String... context)throws Exception {JSONArray ids=new JSONArray();for(String id:context)ids.put(id);long at=BASE+(sequence++)*60000L;JSONObject m=new JSONObject().put("id",UUID.randomUUID().toString()).put("role","user").put("content",text).put("files",new JSONArray()).put("created",at).put("capturedAt",at).put("capturedZone","Asia/Shanghai").put("contextMessageIds",ids);db.put("messages",m);return m;}
  private static JSONObject subject(String qualifier)throws Exception {return new JSONObject().put("name","内核体验小林").put("kind","person").put("qualifier",qualifier);}
  private static JSONObject fact(String qualifier,String predicate,String value)throws Exception {return new JSONObject().put("kind","fact").put("type","preference").put("title","内核体验小林的"+predicate).put("content",value).put("subject",subject(qualifier)).put("predicate",predicate).put("value",value);}
  private static JSONObject plan(String text,String raw,boolean reminder)throws Exception {JSONObject p=new JSONObject().put("kind","intent").put("type","task").put("title",text).put("content",text).put("temporal",new JSONObject().put("raw",raw).put("source","user"));if(reminder)p.put("reminder",new JSONObject().put("raw",raw).put("source","user"));return p;}
  private static JSONObject apply(Store db,JSONObject source,JSONObject p)throws Exception {MemoryLedger ledger=new MemoryLedger(db);ledger.apply(source,new JSONObject().put("intent","record").put("memories",new JSONArray().put(p)),ledger.search(source.optString("content"),100,source));JSONArray ids=source.getJSONArray("memoryIds");ok(ids.length()==1,"One record saved or updated");return db.one("memories",ids.getString(0));}
  private static boolean indexedAttention(Store db,String id){try(Cursor c=db.getReadableDatabase().rawQuery("SELECT 1 FROM memory_attention WHERE memory_id=?",new String[]{id})){return c.moveToFirst();}}
  public static void run(Store db,Context context)throws Exception {
    MemoryLedger ledger=new MemoryLedger(db);JSONObject sourceA=message(db,"同事内核体验小林喜欢美式"),a=apply(db,sourceA,fact("同事","饮料","美式"));JSONObject sourceB=message(db,"大学同学内核体验小林喜欢拿铁"),b=apply(db,sourceB,fact("大学同学","饮料","拿铁"));
    JSONObject source=message(db,"改天请内核体验小林吃饭",sourceA.getString("id"));JSONObject p=plan("请内核体验小林吃饭","改天",false).put("subject",subject("").put("id",b.getString("subjectId")));JSONObject flexible=apply(db,source,p);ok(flexible.getString("subjectId").equals(a.getString("subjectId")),"Unique recent same-name context overrides a model-selected wrong ID");ok(flexible.optString("referenceBasis").contains("上下文")&&flexible.optBoolean("referenceAssumed"),"Context association retains its basis");ok(flexible.getJSONObject("time").optString("state").equals("unscheduled"),"Some other day is an ordinary unscheduled plan");ok(flexible.getJSONObject("care").optString("level").equals("quiet")&&!indexedAttention(db,flexible.getString("id")),"An unscheduled plan is not an attention debt");ok(MemoryCare.canArchive(flexible)&&!MemoryCare.canAutoRemind(flexible),"Archiving and automatic reminders use distinct risk checks");
    flexible=ledger.edit(new JSONObject().put("id",flexible.getString("id")).put("status","completed"),"");flexible.put("completedAt",System.currentTimeMillis()-9L*86400000L).put("longTerm",false);db.put("memories",flexible);db.archive(true);ok(db.one("memories",flexible.getString("id")).optString("status").equals("archived"),"A completed unscheduled task can be archived");ok(db.one("messages",source.getString("id")).getString("content").equals("改天请内核体验小林吃饭")&&ledger.history(flexible.getString("id")).length()>=2,"Original input and earlier versions survive completion and archive");
    JSONObject both=message(db,"同事内核体验小林和大学同学内核体验小林都来了");both.put("focusEntityIds",new JSONArray().put(a.getString("subjectId")).put(b.getString("subjectId")));db.put("messages",both);JSONObject ambiguous=apply(db,message(db,"改天请内核体验小林喝咖啡",both.getString("id")),plan("请内核体验小林喝咖啡","改天",false).put("subject",subject("")));ok(ambiguous.optString("referenceState").equals("unresolved")&&ambiguous.getJSONObject("care").optString("level").equals("optional")&&!indexedAttention(db,ambiguous.getString("id")),"Genuine ordinary ambiguity stays in the background");
    JSONObject yearSource=message(db,"3月1日去看展"),year=apply(db,yearSource,plan("看展","3月1日",false));ok(year.getJSONObject("time").optLong("start")==OffsetDateTime.parse("2031-03-01T00:00:00+08:00").toInstant().toEpochMilli()&&year.getJSONObject("time").optBoolean("assumed"),"User plans choose the nearest future year and retain the assumption");JSONObject past=apply(db,message(db,"3月1日去过看展"),new JSONObject().put("kind","event").put("type","event").put("eventState","occurred").put("content","看展已经发生").put("temporal",new JSONObject().put("raw","3月1日").put("source","user")));ok(past.getJSONObject("time").optLong("start")==OffsetDateTime.parse("2030-03-01T00:00:00+08:00").toInstant().toEpochMilli(),"Occurred events choose the nearest past year");
    JSONObject weekdaySource=message(db,"周二去图书馆"),weekday=apply(db,weekdaySource,plan("去图书馆","周二",false));long expected=Instant.ofEpochMilli(weekdaySource.getLong("capturedAt")).atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().with(TemporalAdjusters.nextOrSame(DayOfWeek.TUESDAY)).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli();ok(weekday.getJSONObject("time").optLong("start")==expected&&weekday.getJSONObject("time").optBoolean("assumed")&&!MemoryCare.actionable(weekday),"Bare weekdays use the fixed source calendar without demanding confirmation");
    JSONObject externalSource=message(db,"我存了这段资料");externalSource.put("linkText","明天开会");db.put("messages",externalSource);JSONObject external=apply(db,externalSource,plan("资料里的开会安排","明天",false).put("temporal",new JSONObject().put("raw","明天").put("source","link")));ok(external.getJSONObject("time").optString("state").equals("source_time_unknown")&&!MemoryCare.actionable(external),"Unknown external author time is retained without import-time guessing or a question");
    JSONObject different=apply(db,message(db,"同事内核体验小林喜欢浓缩"),fact("同事","饮料","浓缩"));ok(different.optString("truthState").equals("disputed")&&!MemoryCare.actionable(different)&&!indexedAttention(db,different.getString("id")),"A low-risk preference conflict preserves both claims quietly");JSONObject edited=ledger.edit(new JSONObject().put("id",a.getString("id")).put("content","用户手工补充的口味"),"");ok(edited.optBoolean("structuredReview")&&!MemoryCare.actionable(edited),"Manual factual structure review remains conservative and stays in the background");
    JSONObject self=apply(db,message(db,"现在不吃辣了"),fact("","自己的口味","不吃辣").put("subject",new JSONObject().put("name","我").put("kind","self")));ok(self.optString("referenceState").equals("resolved")&&!MemoryCare.actionable(self),"An ordinary implicit self description does not require a subject question");
    JSONObject remindSource=message(db,"明天提醒我浇花"),remind=apply(db,remindSource,plan("浇花","明天",true));ok(remind.getJSONObject("care").optString("level").equals("actionable")&&remind.getJSONObject("care").optString("kind").equals("reminder_time")&&indexedAttention(db,remind.getString("id")),"An actual reminder without a clock asks one useful question");ok(!MemoryCare.canAutoRemind(remind)&&remind.optLong("remindAt")==0,"Unknown reminder clocks never schedule automatically");
    JSONObject answer=message(db,"晚上8点",remindSource.getString("id"));answer.put("capturedZone","America/Los_Angeles");db.put("messages",answer);JSONObject completed=apply(db,answer,plan("晚上8点","晚上8点",false).put("reminder",new JSONObject().put("raw","晚上8点").put("source","user").put("referenceId",remind.getString("id"))));ok(completed.getString("id").equals(remind.getString("id"))&&answer.getJSONArray("memoryIds").optString(0).equals(remind.getString("id")),"A clock-only answer updates the unique preceding reminder");ok(completed.optLong("remindAt")==OffsetDateTime.parse("2030-10-10T20:00:00+08:00").toInstant().toEpochMilli(),"The answer retains tomorrow and the original captured zone");ok(MemoryCare.canAutoRemind(completed)&&completed.getJSONObject("care").optString("level").equals("quiet"),"A verified minute makes the reminder eligible without another question");ok(completed.getJSONObject("reminderTime").getJSONObject("anchor").optLong("capturedAt")==remindSource.optLong("capturedAt")&&completed.getJSONObject("reminderTime").getJSONArray("provenance").length()==2&&completed.getJSONArray("sourceIds").length()==2,"Date and clock retain separate utterances and the original date anchor");ok(db.one("messages",remindSource.getString("id")).optString("content").equals("明天提醒我浇花")&&db.one("messages",answer.getString("id")).optString("content").equals("晚上8点"),"Clock completion never fabricates a combined original sentence");
    JSONObject group=message(db,"明天提醒我擦窗，也提醒我喂鱼");ledger.apply(group,new JSONObject().put("memories",new JSONArray().put(plan("擦窗","明天",true)).put(plan("喂鱼","明天",true))),new JSONArray());JSONArray groupIds=group.getJSONArray("memoryIds");ok(groupIds.length()==2,"Two actual reminders can share one source");ledger.deferCare(groupIds.getString(0));for(int i=0;i<groupIds.length();i++){JSONObject r=db.one("memories",groupIds.getString(i));ok(r.getJSONObject("care").optBoolean("deferred")&&!MemoryCare.actionable(r)&&!indexedAttention(db,r.getString("id")),"Later suppresses every reminder from the same source, including after reload");}
    JSONObject after=apply(db,message(db,"晚上8点",group.getString("id")),plan("晚上8点","晚上8点",false).put("reminder",new JSONObject().put("raw","晚上8点").put("source","user").put("referenceId",groupIds.getString(1))));ok(after.optLong("remindAt")==0&&!after.getString("id").equals(groupIds.getString(1))&&!MemoryCare.actionable(after),"A plain clock after deferring is not chased into an old reminder");
    JSONObject newRequest=apply(db,message(db,"明天晚上8点提醒我擦窗"),plan("擦窗","明天晚上8点",true));ok(MemoryCare.canAutoRemind(newRequest)&&!newRequest.getJSONObject("care").optBoolean("deferred"),"A new explicit reminder request can start a new arrangement");ok(!MemoryCare.requestsReminder("不用提醒我")&&MemoryCare.requestsReminder("别忘了提醒我"),"Reminder intent respects ordinary negative and positive wording");ok(TimeAnchor.resolve("明天8点",remindSource,false,null,"future").optString("state").equals("ambiguous_clock"),"An unspecified AM/PM clock remains unsafe for automatic reminders");
    System.out.println("Assistant feel checks passed: "+checks+"; quiet records, fixed assumptions, safe reminder follow-up and shared-source deferral");
  }
}
